public static void Apply(){var b=new StringBuilder();try{var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByPath("Assets/ArtStyleTest/Scenes/out.unity");if(!scene.isLoaded||EditorApplication.isPlaying)throw new Exception("Open out in Edit mode");string backup="Assets/ArtStyleTest/Scenes_BACKUP/out_before_turf_controls_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";if(!EditorSceneManager.SaveScene(scene,backup,true))throw new Exception("Backup failed");b.AppendLine("backup="+backup);var root=scene.GetRootGameObjects().First(g=>g.name=="grass").transform.Find("远景建筑草皮");var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/ArtStyleTest/OutAssets/grass/Materials/Distant_Turf.mat");int surfaces=0;foreach(var binding in root.GetComponentsInChildren<SurfaceGrassBinding>(true)){var source=binding.surface.GetComponent<MeshFilter>().sharedMesh;var target=binding.GetComponentInChildren<MeshFilter>().sharedMesh;var renderer=binding.surface.GetComponent<MeshRenderer>();var sourceVertices=source.vertices;var sourceNormals=source.normals;var indices=source.triangles;var vs=new List<Vector3>();var ns=new List<Vector3>();var uv=new List<Vector4>();var normalMatrix=binding.surface.localToWorldMatrix.inverse.transpose;for(int t=0;t<indices.Length;t+=3){var normals=new[]{normalMatrix.MultiplyVector(sourceNormals[indices[t]]).normalized,normalMatrix.MultiplyVector(sourceNormals[indices[t+1]]).normalized,normalMatrix.MultiplyVector(sourceNormals[indices[t+2]]).normalized};if(normals.Max(n=>n.y)<-.35f)continue;for(int j=0;j<3;j++){int i=indices[t+j];var world=binding.surface.TransformPoint(sourceVertices[i])+normals[j]*.025f;vs.Add(binding.surface.InverseTransformPoint(world));ns.Add(sourceNormals[i]);uv.Add(new Vector4(Mathf.InverseLerp(renderer.bounds.min.y,renderer.bounds.max.y,world.y),0,0,0));}}target.Clear();target.indexFormat=IndexFormat.UInt32;target.SetVertices(vs);target.SetNormals(ns);target.SetUVs(0,uv);target.SetTriangles(Enumerable.Range(0,vs.Count).ToArray(),0);target.RecalculateBounds();EditorUtility.SetDirty(target);surfaces++;}Undo.RecordObject(material,"Add adjustable turf appearance");material.SetColor("_TurfColour",new Color(.12f,.30f,.06f,1));material.SetFloat("_Coverage",.54f);material.SetFloat("_PatchSize",8);material.SetFloat("_TopBias",.20f);material.SetFloat("_EdgeBreakup",.015f);EditorUtility.SetDirty(material);var settings=root.GetComponent<DistantTurfControl>();if(!settings)settings=root.gameObject.AddComponent<DistantTurfControl>();settings.grassMaterial=material;EditorUtility.SetDirty(settings);int errors=ShaderUtil.GetShaderMessages(material.shader).Count(m=>m.severity.ToString()=="Error");if(errors>0)throw new Exception(string.Join("\n",ShaderUtil.GetShaderMessages(material.shader).Select(m=>m.message)));AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var camera=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai");var capture=typeof(OutReferenceComposition).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);try{material.SetFloat("_Coverage",0);capture.Invoke(null,new object[]{camera,O+"Out_turf_coverage_zero_check.png"});material.SetFloat("_Coverage",1);capture.Invoke(null,new object[]{camera,O+"Out_turf_coverage_full_check.png"});}finally{material.SetFloat("_Coverage",.54f);EditorUtility.SetDirty(material);AssetDatabase.SaveAssets();}capture.Invoke(null,new object[]{camera,O+"Out_editable_turf_coverage.png"});Selection.activeGameObject=root.gameObject;EditorGUIUtility.PingObject(root);b.AppendLine("surfaces="+surfaces+" shaderErrors="+errors+" coverage=.54 patchSize=8 editableColour=True saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_turf_controls_result.txt",b.ToString());}
